import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({Key? key}) : super(key: key);  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  String _expression = '';  String _result = '';  void _onPressed(String value) {    setState(() {      if (value == '=') {        try {          _result = _calculate(_expression);          _expression = _result;        } catch (e) {          _result = 'Error';          _expression = '';        }      } else if (value == 'C') {        _expression = '';        _result = '';      } else {        _expression += value;      }    });  }  String _calculate(String expression) {    try {      return expression          .replaceAll(' ', '')          .replaceAll('+', '+')          .replaceAll('-', '-')          .replaceAll('*', '*')          .replaceAll('/', '/')          .replaceAll('%', '%')          .replaceAll('(', '(')          .replaceAll(')', ')')          .splitMapJoin(            RegExp(r'[+*/()-]'),            onMatch: (m) => m.group(0)!,            onNonMatch: (n) => n,          )          .split('')          .map((e) => e)          .join('');      var result = num.parse(expression).toDouble();      return result.toString();    } catch (e) {      return 'Error';    }  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Calculator'),      ),      body: Column(        children: [          Expanded(            child: Container(              padding: const EdgeInsets.all(20),              child: Column(                mainAxisAlignment: MainAxisAlignment.end,                children: [                  Text(                    _expression,                    style: const TextStyle(fontSize: 24),                  ),                  const SizedBox(height: 20),                  Text(                    _result,                    style: const TextStyle(fontSize: 48),                  ),                ],              ),            ),          ),          Expanded(            flex: 2,            child: GridView.count(              crossAxisCount: 4,              childAspectRatio: 1.5,              children: [                CalculatorButton(                  onPressed: _onPressed,                  value: '7',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '8',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '9',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '/',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '4',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '5',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '6',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '*',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '1',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '2',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '3',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '-',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '0',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '.',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '%',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '+',                ),                CalculatorButton(                  onPressed: _onPressed,                  value: 'C',                  isClear: true,                ),                CalculatorButton(                  onPressed: _onPressed,                  value: '=',                  isEquals: true,                ),              ],            ),          ),        ],      ),    );  }}class CalculatorButton extends StatelessWidget {  final Function(String) onPressed;  final String value;  final bool isClear;  final bool isEquals;  const CalculatorButton({    Key? key,    required this.onPressed,    required this.value,    this.isClear = false,    this.isEquals = false,  }) : super(key: key);  @override  Widget build(BuildContext context) {    return GestureDetector(      onTap: () => onPressed(value),      child: Container(        margin: const EdgeInsets.all(5),        decoration: BoxDecoration(          color: isClear              ? Colors.redAccent              : isEquals                  ? Colors.blueAccent                  : Colors.grey[200],          borderRadius: BorderRadius.circular(10),        ),        child: Center(          child: Text(            value,            style: TextStyle(              fontSize: 24,              color: isClear || isEquals ? Colors.white : Colors.black,            ),          ),        ),      ),    );  }}